//go:build integration

package live_test

// Parity oracle (added by tools/parity overlay, never committed upstream):
// when OPUTE_STANDALONE_BINARY is set, the live helpers start that binary as
// a standalone agent on the local Incus (inside a disposable nested-Incus
// twin) instead of the in-process Go server, and the go-sdk client reaches
// it over HTTP with a per-process bearer token. The tests themselves are
// unchanged.

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"net"
	"net/http"
	"net/http/httptest"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

var parityToken string

type parityBearer struct{ token string }

func (b parityBearer) RoundTrip(r *http.Request) (*http.Response, error) {
	r = r.Clone(r.Context())
	r.Header.Set("Authorization", "Bearer "+b.token)
	return http.DefaultTransport.RoundTrip(r)
}

func parityExternal() bool { return os.Getenv("OPUTE_STANDALONE_BINARY") != "" }

func parityHTTPClient() *http.Client {
	if parityToken == "" {
		return nil
	}
	return &http.Client{Transport: parityBearer{token: parityToken}}
}

func parityExternalServer(t *testing.T, extra ...string) *httptest.Server {
	t.Helper()
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	port := listener.Addr().(*net.TCPAddr).Port
	_ = listener.Close()
	raw := make([]byte, 24)
	if _, err := rand.Read(raw); err != nil {
		t.Fatal(err)
	}
	parityToken = hex.EncodeToString(raw)
	root := t.TempDir()
	env := []string{}
	for _, assignment := range os.Environ() {
		key, _, _ := strings.Cut(assignment, "=")
		if strings.HasPrefix(key, "OPUTE_") || key == "MCP_AUTH_TOKEN" || key == "HOST_MCP_PORT" {
			continue
		}
		env = append(env, assignment)
	}
	env = append(env,
		"OPUTE_REMOTE_AGENT_ID=go-live-parity-agent",
		"OPUTE_AGENT_MODE=standalone",
		"OPUTE_INFRA_PROVIDER_ID=incus",
		"OPUTE_STANDALONE_ALLOW_MUTATIONS=true",
		"OPUTE_STANDALONE_STATE_DIR="+filepath.Join(root, "state"),
		"OPUTE_HOST_AGENT_INSTANCE_ROOT="+filepath.Join(root, "instance"),
		"OPUTE_HOST_AGENT_RELAY_DIR="+filepath.Join(root, "relay"),
		"HOST_MCP_BIND_HOST=127.0.0.1",
		fmt.Sprintf("HOST_MCP_PORT=%d", port),
		"MCP_AUTH_TOKEN="+parityToken,
	)
	env = append(env, extra...)
	ctx, cancel := context.WithCancel(context.Background())
	cmd := exec.CommandContext(ctx, os.Getenv("OPUTE_STANDALONE_BINARY"), "serve", "--mode=standalone")
	cmd.Env = env
	cmd.Stdout, cmd.Stderr = os.Stderr, os.Stderr
	if err := cmd.Start(); err != nil {
		cancel()
		t.Fatal(err)
	}
	t.Cleanup(func() {
		_ = cmd.Process.Signal(os.Interrupt)
		done := make(chan struct{})
		go func() { _, _ = cmd.Process.Wait(); close(done) }()
		select {
		case <-done:
		case <-time.After(30 * time.Second):
			cancel()
			<-done
		}
		cancel()
	})
	base := fmt.Sprintf("http://127.0.0.1:%d", port)
	deadline := time.Now().Add(30 * time.Second)
	for {
		res, err := http.Get(base + "/health")
		if err == nil {
			res.Body.Close()
			if res.StatusCode == http.StatusOK {
				break
			}
		}
		if time.Now().After(deadline) {
			t.Fatalf("agent not ready: %v", err)
		}
		time.Sleep(100 * time.Millisecond)
	}
	return &httptest.Server{URL: base}
}

