func newLiveServer(t *testing.T) (*hostmcp.Server, *httptest.Server) {
	t.Helper()
	if parityExternal() {
		return nil, parityExternalServer(t)
	}

func newLiveServerWithOwnership(t *testing.T, instanceID, checkpointPath string) (*hostmcp.Server, *httptest.Server) {
	t.Helper()
	if parityExternal() {
		return nil, parityExternalServer(t, "OPUTE_HOST_AGENT_INSTANCE="+instanceID,
			"OPUTE_INCUS_OWNERSHIP_MODE=enforce", "OPUTE_SHARED_HOST_OWNER_INSTANCE="+instanceID)
	}
